+    FT_CMap*  first = face->dmap_charmaps;
+    FT_CMap*  cur;
+
+
+    if ( !first )
+      return NULL;
+
+    cur = first + face->num_dmap_charmaps;
+    for ( ; --cur >= first; )
+    {
+      FT_CMap  cmap = cur[0];
