+             cmap->charmap.encoding_id == TT_APPLE_ID_UNICODE_32    )  ||
+           ( cmap->charmap.platform_id == TT_PLATFORM_APPLE_UNICODE  &&
+             cmap->charmap.encoding_id == TT_APPLE_ID_FULL_UNICODE   &&
