+    cur = first + face->num_dmap_charmaps;
+    for ( ; --cur >= first; )
+    {
+      FT_CMap  cmap = cur[0];
+
+
+      if ( cmap                                              &&
+           !tt_cmap_is_variation( cmap )                     &&
+           cmap->charmap.platform_id == charmap->platform_id &&
+           cmap->charmap.encoding_id == charmap->encoding_id )
+        return cmap;
+    }
+
+    cur = first + face->num_dmap_charmaps;
+    for ( ; --cur >= first; )
