+    dmap_glyph = ttcmap->dmap->clazz->char_next( ttcmap->dmap, &dmap_char );
+    cmap_glyph = ttcmap->cmap_class->char_next( cmap, &cmap_char );
+
+    if ( dmap_glyph && ( !cmap_glyph || dmap_char <= cmap_char ) )
+    {
+      *achar_code = dmap_char;
+      return dmap_glyph;
+    }
+
+    *achar_code = cmap_char;
+    return cmap_glyph;
+  }
